from voice_v3 import O,key,save
import subprocess,json,numpy as np,httpx,base64
source=O/'narration-tight-resolve-smooth.mov';probe=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_streams','-show_format','-of','json',str(source)]));save('resolve-voice-probe.json',probe);print([(s['codec_type'],s.get('codec_name'),s.get('duration')) for s in probe['streams']],flush=True)
# Audio conversion/mixing only: all speech cuts were made in Resolve.
